app.get("/admin", (req, res) => {
  const token = req.query.token;

  if (!token) {
    return res.status(401).send("Authentication token required.");
  }

  try {
    const decoded = jwt.verify(token, SECRET);

    if (decoded.admin) {
      res.send("Welcome admin");
    } else {
      res.status(403).send("Forbidden: Not an admin");
    }
  } catch (err) {
    if (err.name === 'TokenExpiredError') {
      return res.status(401).send("Unauthorized: Token expired.");
    }
    if (err.name === 'JsonWebTokenError') {
      return res.status(401).send("Unauthorized: Invalid token.");
    }
    // Catch any other unexpected errors during verification
    return res.status(500).send("Internal server error during token verification.");
  }
});

function escapeHtml(text) {
  const map = {
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    "\"": "&quot;",
    "'": "&#039;"
  };
  return text.replace(/[&<>"]|'(?=[^>]*<)/g, function(m) { return map[m]; });
}
